def transform(grid):
    out = [row[:] for row in grid]
    fours = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 4]
    sixes = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 6]
    if not fours or not sixes:
        return out

    r0 = min(r for r, _ in sixes)
    r1 = max(r for r, _ in sixes)
    c0 = min(c for _, c in sixes)
    c1 = max(c for _, c in sixes)
    h, w = r1 - r0 + 1, c1 - c0 + 1
    local = {(r - r0, c - c0) for r, c in sixes}

    if h == 3 and w >= 4 and local == ({(1, c) for c in range(w)} | {(0, (w - 1) // 2 + 1), (2, (w - 1) // 2 + 1)}):
        arrow = "right"
    elif h == 3 and w >= 4 and local == ({(1, c) for c in range(w)} | {(0, (w - 1) // 2), (2, (w - 1) // 2)}):
        arrow = "left"
    elif w >= 3 and h >= 3 and local == ({(0, c) for c in range(w)} | {(r, w // 2) for r in range(1, h)}):
        arrow = "up"
    elif w >= 3 and h >= 3 and local == ({(h - 1, c) for c in range(w)} | {(r, w // 2) for r in range(h - 1)}):
        arrow = "down"
    else:
        arrow = "right"

    side = {"right": "down", "down": "left", "left": "up", "up": "right"}[arrow]
    for r, c in sixes:
        out[r][c] = 0
    if side == "down":
        edge = max(r for r, _ in fours)
        reflected = [(2 * edge + 1 - r, c) for r, c in fours]
    elif side == "up":
        edge = min(r for r, _ in fours)
        reflected = [(2 * edge - 1 - r, c) for r, c in fours]
    elif side == "right":
        edge = max(c for _, c in fours)
        reflected = [(r, 2 * edge + 1 - c) for r, c in fours]
    else:
        edge = min(c for _, c in fours)
        reflected = [(r, 2 * edge - 1 - c) for r, c in fours]
    for r, c in reflected:
        if 0 <= r < len(out) and 0 <= c < len(out[0]):
            out[r][c] = 4
    return out

